function update(){if(!state)return;const night=state.settings.theme==='night'||(state.settings.theme==='auto'&&Math.floor(state.worldTick/600)%2===1);$('shell').classList.toggle('night',night);$('shell').classList.toggle('reduced',state.settings.reducedMotion);{const c=F.Environment.calendar(state);$('season').textContent=c.name+' '+c.day+'일째';$('season').dataset.season=c.id;}$('weather').textContent=({morning:'이른 햇살',noon:'햇살이 드는 낮',dusk:'노을이 드는 숲',night:'달빛이 드는 밤',deep:'고요한 깊은 밤',dawn:'이슬 맺힌 새벽'}[F.Environment.timeKey(state)])+' · '+F.Environment.NAMES[F.Environment.weatherKey(state)];
 /* 0.8.2 (user: "안내 문구는 해당 안내가 필요할 때만 5초 정도 떴다가 사라지게 … 월드 하단 중간"): a hint appears only when
    something new needs saying (a guest, a thirsty friend, rain starting, a small neighbour by the rocks) and fades after 5 s */
 {const thirsty=state.individuals.find(x=>x.active&&!x.mounted&&x.B<35),lakeEv=[...state.events].reverse().find(e=>e.type==='world'&&state.worldTick-e.tick<=6),msg=lakeEv?lakeEv.text:state.recruitment.visitor?F.Recruitment.josa(state.recruitment.visitor.pet.name,'이','가')+' 찾아왔어요 · 눌러서 만나기':thirsty?thirsty.name+' · 목이 말라 물을 찾아가요.':state.weather.kind==='rain'?'비가 내리면, 자리마다 물기가 달라져요.':state.neighbor.stage==='visiting'?'바위 틈에 작은 이웃이 쉬고 있어요.':'',now=performance.now();
  if(msg!==hintMsg){hintMsg=msg;hintUntil=msg?now+5000:0;if(msg)$('hint').textContent=msg;}
  $('hint').hidden=!!inspector;$('hint').classList.toggle('show',!!msg&&now<hintUntil&&state.settings.showSpeech&&!editor&&!carry.session);}
 $('world-note').textContent=editor?'배치를 살펴보는 동안에도 게임 시간은 흘러요.':'';if(tab==='visit'){if(state.recruitment.visitor)updateVisit();else{switchTab('friends');notice('친구가 잠시 돌아갔어요. 함께한 기록은 이어져요.');}}showCard();if(native)native.theme(night);}
