 if(b.dataset.move){const id=scene.selectedPatch,p=scene.preview[id]||(id==='spring'?state.spring:state.patches.find(x=>x.id===id));const delta={left:[-.025,0],right:[.025,0],up:[0,-.025],down:[0,.025]}[b.dataset.move];scene.preview[id]={x:p.x+delta[0],y:p.y+delta[1]};renderEditor();return;}
 if(b.dataset.toggle){const k=b.dataset.toggle;commit(s=>{if(k==='mounted'){const p=s.individuals.find(p=>p.id===selected)||s.individuals[0];F.Social.cancel(s,p.id);F.Objects.release(s,p,'mounted');p.mounted=!p.mounted;}else s.settings[k]=!(s.settings[k]??(k==='showFrame'));},()=>{renderPage();targets();});return;}
 if(a==='roster'){commit(s=>F.roster(s,b.dataset.id,!s.individuals.find(p=>p.id===b.dataset.id).active),()=>{renderPage();targets();});return;}
 if(a==='stage-lab'){startInspector();return;}
 if(a==='inspect'){startInspector();return;}if(a==='admin'){switchTab('admin');return;}if(a==='admin-back'){switchTab('settings');return;}if(a==='admin-run'){const args=JSON.parse(b.dataset.args),run=()=>{let msg='';if(commit(s=>{msg=window.ForestAdmin.run(F,s,...args);},()=>{renderPage();targets();}))notice(msg);};if(args[0]==='resetLevels'||args[0]==='openLake'||args[0].startsWith('unlock'))dialog('정말 할까요?',{resetLevels:'모든 친구의 레벨과 성장 경험이 처음으로 돌아가요.',openLake:'숲 성장 조건과 동쪽 산책을 건너뛰고 물가를 열어요. 다시 닫을 수 없어요.'}[args[0]]||'해금은 다시 닫을 수 없어요.',[{label:'취소',fn:closeDialog},{label:'하기',fn:()=>{closeDialog();run();}}]);else run();return;}if(a==='open-lake'){dialog('호수 물가를 바로 열까요?','관리자 기능이에요. 숲 성장 조건과 동쪽 산책을 건너뛰고 지금 물가를 열어요. 다시 닫을 수는 없어요.',[{label:'취소',fn:closeDialog},{label:'열기',fn:()=>{closeDialog();commit(s=>{F.World.openLake(s);},()=>{renderPage();notice('숲 동쪽에 물가가 열렸어요. 화면을 오른쪽으로 끌어 보세요.');});}}]);return;}
 if(a==='inspect-close'){endInspector();return;}
 if(a==='inspect-play'){inspector.playing=!inspector.playing;renderInspector();return;}
